def strip_blog_cards(html: str) -> str:
    html = re.sub(
        r'\s*<div class="lp-card">\s*<h2>Verwandte Themen</h2>[\s\S]*?</div>',
        "",
        html,
        count=2,
    )
    html = re.sub(
        r'\s*<div class="lp-card">\s*<h2>Related reading</h2>[\s\S]*?</div>',
        "",
        html,
        count=2,
    )
    html = re.sub(
        r'\s*<div class="lp-card">\s*<h2>Guides worth reading first</h2>[\s\S]*?</div>',
        "",
        html,
        count=2,
    )
    # related reading as lp-sections block that only contains blog lists
    html = re.sub(
        r'<section class="lp-sections">\s*<div class="lp-sections-inner">\s*<div class="lp-card">\s*<h2>Verwandte Themen</h2>[\s\S]*?</section>',
        "",
        html,
        count=1,
    )
    return html


