def polish_file(path: Path) -> None:
    html = path.read_text(encoding="utf-8")
    orig = html
    for old, new in BLOG_TO_CLUSTER:
        html = html.replace(old, new)
    pairs = T() + body_pairs() + extra_product()
    pairs.sort(key=lambda x: len(x[0]), reverse=True)
    for old, new in pairs:
        html = html.replace(old, new)
    html = strip_blog_cards(html)
    # leftover mixed
    html = html.replace("Nicht-resident Eigentümerhip", "Nicht-resident Eigentum")
    html = html.replace("Get a Autoversicherung Quote", "Autoversicherung anfragen")
    html = html.replace("Get a Krankenversicherung Quote", "Krankenversicherung anfragen")
    html = html.replace("<strong>Health insurance</strong>", "<strong>Krankenversicherung</strong>")
    html = html.replace("<strong>Home insurance</strong>", "<strong>Hausversicherung</strong>")
    html = html.replace("<strong>Landlord insurance</strong>", "<strong>Vermieterversicherung</strong>")
    html = html.replace("<strong>Car insurance</strong>", "<strong>Autoversicherung</strong>")
    html = html.replace("<strong>Life insurance</strong>", "<strong>Lebensversicherung</strong>")
    html = html.replace("<strong>Private clients</strong>", "<strong>Private Clients</strong>")
    html = html.replace("<strong>Health</strong>", "<strong>Krankenversicherung</strong>")
    if html != orig:
        path.write_text(html, encoding="utf-8")
        print("  updated", path.parent.name, "delta", len(html) - len(orig))
    else:
        print("  unchanged", path.parent.name)


def leftover_count(path: Path) -> int:
    html = path.read_text(encoding="utf-8")
    html = re.sub(r"<script[\s\S]*?</script>", " ", html)
    html = re.sub(r"<style[\s\S]*?</style>", " ", html)
    n = 0
    for m in re.finditer(r">([^<]{20,})<", html):
        t = " ".join(m.group(1).split())
        if re.search(r"\b(the|and|your|for|with|this|insurance|cover|quote|already|typically|please)\b", t, re.I):
            n += 1
    return n


def main():
    print("Polishing DE Spain pages (PT product pages not touched)")
    for d in sorted((ROOT / "public/de").glob("*spanien*")):
        polish_file(d / "index.html")
        print("    leftover-ish", leftover_count(d / "index.html"))


if __name__ == "__main__":
    main()
